; palette.asm -- chapter 1: the sixteen colour codes
; generated by gen01.py
        INCLUDE "msx.inc"
        OUTPUT "palette.rom"
        ORG $4000
        CART_HEADER init

NAMES   EQU $1800
COLOURS EQU $2000
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while we set up
        VDP_REG 0, $00          ; Graphic I
        VDP_REG 2, NAMES / $400
        VDP_REG 3, COLOURS / $40
        VDP_REG 4, $00
        VDP_REG 5, $36
        VDP_REG 6, $07
        VDP_REG 7, $01          ; border black
        VRAM_WRITE $0000        ; patterns 8*c solid, the others empty
        ld d, 0
.pat:   ld a, d
        and 7
        ld a, 0
        jr nz, .empty
        dec a
.empty: ld b, 8
.row:   out (VDP_DATA), a
        djnz .row
        inc d
        jr nz, .pat
        VRAM_WRITE COLOURS      ; group c: ink c, paper 0
        xor a
.grp:   push af
        add a, a
        add a, a
        add a, a
        add a, a
        out (VDP_DATA), a
        pop af
        inc a
        cp 32
        jr nz, .grp
        VRAM_WRITE $1B00
        ld a, $D0
        out (VDP_DATA), a
        VRAM_WRITE NAMES        ; 4 x 4 swatches of 7 x 6 tiles
        ld e, 0
.nrow:  ld d, 0
.ncol:  ld a, d
        srl a
        srl a
        srl a
        ld b, a
        ld a, e
        ld c, 0
.div6:  cp 6
        jr c, .q
        sub 6
        inc c
        jr .div6
.q:     ld a, c
        add a, a
        add a, a
        add a, b
        add a, a
        add a, a
        add a, a
        ld c, a
        ld a, d
        and 7
        cp 7
        ld a, c
        jr nz, .put
        ld a, 1
.put:   out (VDP_DATA), a
        inc d
        ld a, d
        cp 32
        jr nz, .ncol
        inc e
        ld a, e
        cp 24
        jr nz, .nrow
        VDP_REG 1, $C0
done:   jr done
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
